/**
 * Shared CLI configuration.
 *
 * Single source of truth for:
 *   - Output directory path
 *   - Date resolution (today, yesterday, Nd, YYYY-MM-DD)
 *   - Time range construction
 *   - Common argument parsing helpers
 *
 * All scripts import from here instead of duplicating these.
 */

import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import type { TimeRange } from '../types.js';

// ── Output directory ──────────────────────────────────────────────────────────

const PROJECT_ROOT = dirname(dirname(dirname(fileURLToPath(import.meta.url))));

/** Canonical output directory. Honors FEEDQ_OUTPUT_ROOT env var. */
export const OUTPUT_DIR: string =
  process.env['FEEDQ_OUTPUT_ROOT'] ??
  join(PROJECT_ROOT, 'output');

// ── Date helpers ──────────────────────────────────────────────────────────────

/** Format a Date as a local-calendar YYYY-MM-DD string. */
export function formatLocalDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** Today's local calendar date as YYYY-MM-DD. */
export function today(): string {
  return formatLocalDate(new Date());
}

/** Resolve a date string: today, yesterday, Nd (relative), or YYYY-MM-DD passthrough. */
export function resolveDate(s: string): string {
  if (s === 'today') return today();
  if (s === 'yesterday') {
    const d = new Date();
    d.setDate(d.getDate() - 1);
    return formatLocalDate(d);
  }
  const m = s.match(/^(\d+)d$/);
