it('counts a scan as scanned regardless of status, but separates a failed scan from a completed one', () => {
  db.recordSourceScan('wirethree', '2026-07-05', 0, 4, 'failed');
  const coverage = resolveCoverage(db, '2026-07-05', '2026-07-05');
  // A failed scan is still 'attempted' (scanned), but must NOT read as a
  // clean scan: it stays out of `complete` and carries its status in
  // `incomplete`, so an empty result over this date is not "nothing
  // published" but "acquisition broke".
  expect(findProvider(coverage, 'wirethree')).toEqual({
    provider: 'wirethree', kind: 'articles',
    scanned: ['2026-07-05'], gaps: [],
    complete: [], incomplete: [{ date: '2026-07-05', status: 'failed' }],
  });

